(function(){'use strict';var _csrf='';function setToken(token){_csrf=token||''}
function generateIdempKey(){if(window.crypto&&typeof crypto.randomUUID==='function'){return crypto.randomUUID()}
return'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,function(c){var r=(Math.random()*16)|0;return(c==='x'?r:(r&0x3)|0x8).toString(16)})}
function post(endpoint,body){var payload=Object.assign({},body,{csrf_token:_csrf,idempotency_key:generateIdempKey()});return fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}).then(function(r){if(!r.ok){return r.json().catch(function(){return{}}).then(function(body){var err=new Error('HTTP '+r.status);err.status=r.status;err.serverError=(body&&body.error)||null;throw err})}
return r.json()})}
window.MwApi={setToken:setToken,post:post}}())